<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>हस्तरेखा रिपोर्ट | भुगतान</title><link rel="stylesheet" href="style.css"><script src="https://checkout.razorpay.com/v1/checkout.js"></script></head><body><div class="topbar">✦ आपकी रिपोर्ट · अगला चरण</div><main class="wrap"><section class="scanner-hero"><div class="eyebrow">02 · रिपोर्ट अनलॉक करें</div><h1>आपकी हथेली तैयार है</h1><p>फोटो की प्रारंभिक गुणवत्ता जांच पूरी हो चुकी है। अब विस्तृत व्यक्तिगत हस्तरेखा रिपोर्ट के लिए एक बार का भुगतान करें।</p></section><section class="card scanner-card payment-card"><div class="summary"><div><span class="section-label">व्यक्तिगत हस्तरेखा रिपोर्ट</span><h2>विस्तृत भविष्य संकेत</h2><p>प्रेम · विवाह · धन · व्यापार · नौकरी · परिवार · अवसर · प्रमुख जीवन चरण</p></div><div class="big-price">₹151</div></div><div class="promise"><div>✓ मुख्य रेखाओं का अध्ययन</div><div>✓ प्रमुख जीवन क्षेत्रों की व्याख्या</div><div>✓ आने वाले समय के संकेत</div><div>✓ संतुलित और व्यावहारिक विवरण</div></div><label class="field">आपका नाम <span>(वैकल्पिक)</span><input id="name" maxlength="80" placeholder="अपना नाम लिखें"></label><button id="payBtn" class="primary">₹151 देकर पूरी रिपोर्ट देखें</button><div id="payStatus" class="status" hidden></div><p class="privacy">भुगतान सुरक्षित checkout के माध्यम से होगा। भुगतान सफल होने के बाद ही रिपोर्ट तैयार होगी।</p></section><section class="info-card"><h2>रिपोर्ट में क्या मिलेगा?</h2><div class="topic-grid"><span>❤️ प्रेम</span><span>💍 विवाह</span><span>💰 धन</span><span>💼 नौकरी</span><span>📈 व्यापार</span><span>🏠 संपत्ति</span><span>👨‍👩‍👧 परिवार</span><span>✨ अवसर</span></div></section></main><script>
const btn=document.getElementById('payBtn'), status=document.getElementById('payStatus');
function msg(t,c='checking'){status.hidden=false;status.className='status '+c;status.textContent=t}
btn.onclick=async()=>{btn.disabled=true;msg('भुगतान सुरक्षित रूप से तैयार किया जा रहा है…');const image=sessionStorage.getItem('palm_image');if(!image){msg('हथेली की फोटो नहीं मिली। वापस जाकर फिर से फोटो चुनें।','error');btn.disabled=false;return}try{const r=await fetch('create-order.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image,name:document.getElementById('name').value.trim()})});const d=await r.json();if(!d.success)throw new Error(d.message||'Order नहीं बन पाया');const options={key:d.key,amount:d.amount,currency:'INR',name:'Palm Reading',description:'Personalized Palm Reading Report',order_id:d.order_id,prefill:{name:document.getElementById('name').value.trim()},theme:{color:'#8a3d45'},handler:async function(resp){msg('भुगतान सत्यापित किया जा रहा है…');const vr=await fetch('verify-payment.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(resp)});const vd=await vr.json();if(!vd.success)throw new Error(vd.message||'Payment verification failed');sessionStorage.removeItem('palm_image');location.href='report.php';},modal:{ondismiss:()=>{msg('भुगतान रद्द किया गया। आप फिर से प्रयास कर सकते हैं।','error');btn.disabled=false}}};new Razorpay(options).open()}catch(e){msg(e.message||'कुछ समस्या हुई। कृपया फिर प्रयास करें।','error');btn.disabled=false}};
</script></body></html>
